import React, { FC } from 'react';
import { isEmpty } from 'lodash-es';
import { phoneFormatter } from '@getvim/atomic-ui';
import { EhrUser } from '@getvim-os/types';
import UserIcon from '../../assets/user.svg';
import EmailIcon from '../../assets/email.svg';
import LocationIcon from '../../assets/location.svg';
import PhoneIcon from '../../assets/phone.svg';
import ShieldIcon from '../../assets/shield.svg';
import RoleIcon from '../../assets/role.svg';
import { UserManagementInfoField } from '../user-management-info-field';
import { UserCenterNeedHelp } from '../user-center-need-help';

import './index.less';

interface ManagementContentProps {
  user?: EhrUser;
  openSupportPanel: () => void;
}

export const ManagementContent: FC<ManagementContentProps> = ({ user, openSupportPanel }) => {
  const phoneNumber = phoneFormatter.valuePhoneNumber(user?.phoneNumber ?? '');

  return (
    <div className="management-user-info">
      <div className="flex flex-col gap-2 flex-1 max-w-[1250px] mx-auto w-full">
        <UserManagementInfoField label="Role" value={user?.roles?.join(', ')} svgIcon={RoleIcon} />
        <div className="divider" />

        <UserManagementInfoField
          label="EHR username"
          value={user?.linkedEhrUser}
          svgIcon={UserIcon}
        />
        <div className="divider" />

        <UserManagementInfoField label="Email" value={user?.email} svgIcon={EmailIcon} />
        <div className="divider" />

        <UserManagementInfoField
          label="Address"
          value={user?.address?.fullAddress}
          svgIcon={LocationIcon}
        />
        <div className="divider" />

        <UserManagementInfoField label="Phone number" value={phoneNumber} svgIcon={PhoneIcon} />
        <div className="divider" />

        <UserManagementInfoField label="NPI" value={user?.npi} svgIcon={ShieldIcon} />
        <div className="divider" />
      </div>
      <div
        className={`user-center-help-cta-wrapper ${isEmpty(user?.roles) ? 'auto-location' : ''}`}
      >
        <UserCenterNeedHelp openSupportPopover={openSupportPanel} />
      </div>
    </div>
  );
};
